enum CurrentFaceState{
    IDLE,
    BLINK,
	CONTENT,
    STATE_COUNT
};

CurrentFaceState faceState = static_cast<CurrentFaceState>(random(0,STATE_COUNT));
// Test comment
void faces()
{
    u8g2.clearBuffer();
    u8g2.setDrawColor(1);
    static unsigned long lastFrame = millis();
    unsigned long interval = 200;
    static unsigned int frame = 0;
    if(millis() - lastFrame > interval){
        switch (faceState)
        {
        case IDLE:
            frame = (frame + 1)%idle_allArray_LEN;
            if(frame == idle_allArray_LEN-1){
                int x = rand() % 10;
                if(x > 7){
                    faceState = static_cast<CurrentFaceState>(random(0,STATE_COUNT));
					frame = 0;
                }
            }
            u8g2.drawBitmap(0, 0, 128 / 8, 64, idle_allArray[frame]);
            break;
        case BLINK:
            frame = (frame + 1)%blink_allArray_LEN;
            if(frame == blink_allArray_LEN-1){
                int x = rand() % 10;
                if(x > 3){
                    faceState = static_cast<CurrentFaceState>(random(0,STATE_COUNT));
					frame = 0;
                }
            }
            u8g2.drawBitmap(0, 0, 128 / 8, 64, blink_allArray[frame]);
            break;
		case CONTENT:
			frame = (frame + 1)%content_allArray_LEN;
            if(frame == content_allArray_LEN-1){
                int x = rand() % 10;
                if(x > 1){
                    CurrentFaceState newState;
					do {
					    newState = static_cast<CurrentFaceState>(random(STATE_COUNT));
						frame = 0;
					} while (newState == faceState);

					faceState = newState;
                }
            }
            u8g2.drawBitmap(0, 0, 128 / 8, 64, content_allArray[frame]);
			break;
        default:
            frame = (frame + 1)%idle_allArray_LEN;
            if(frame == idle_allArray_LEN-1){
                int x = rand() % 10;
                if(x > 7){
                    faceState = static_cast<CurrentFaceState>(random(0,STATE_COUNT));
                }
            }
            u8g2.drawBitmap(0, 0, 128 / 8, 64, idle_allArray[frame]);
            break;
        }
    }
    u8g2.sendBuffer();
}